import { useState, useEffect } from "react";
import { doc, getDoc, setDoc } from "firebase/firestore";
import { db } from "../lib/firebase";

export interface AssetAlert {
    minPercent: number;
    maxPercent: number;
}

export interface AlertConfig {
    minPNL: number;
    maxPNL: number;
    assetAlerts?: Record<string, AssetAlert>;
}

export function useAlerts() {
    const [config, setConfig] = useState<AlertConfig>({ minPNL: -40000, maxPNL: 10000, assetAlerts: {} });
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function load() {
            try {
                const snap = await getDoc(doc(db, "config", "alerts"));
                if (snap.exists()) {
                    const data = snap.data();
                    setConfig({
                        minPNL: data.minPNL ?? -40000,
                        maxPNL: data.maxPNL ?? 10000,
                        assetAlerts: data.assetAlerts ?? {}
                    });
                }
            } catch (e) {
                console.error("Error loading alerts", e);
            } finally {
                setLoading(false);
            }
        }
        load();
    }, []);

    const saveConfig = async (newConfig: AlertConfig) => {
        try {
            await setDoc(doc(db, "config", "alerts"), newConfig, { merge: true });
            setConfig(newConfig);
            return true;
        } catch (e) {
            console.error("Error saving alerts", e);
            return false;
        }
    };

    return { config, loading, saveConfig };
}
